# Loop over input items and add a new field called 'my_new_field' to the JSON of each one
import time

windowHours = 24

return [{
    "json": {
        "sinceUnix": int(time.time()) - windowHours * 3600
    }
}]

def func(_items):
    leaderboard = [i["json"] for i in _items]           # already sorted by score
    run_date = leaderboard[0].get("runDate") if leaderboard else None
    raw_metrics = {i["entity"]: i["rawMetrics"] for i in leaderboard}
    return [{"json": {
        "run_date": run_date,
        "window_hours": 24,
        "leaderboard": leaderboard,
        "raw_metrics": raw_metrics,
        "complete": len(leaderboard) == len(_items) and len(leaderboard) > 0,
        "watchlist_version": "v1"
    }}]

return func(_items)

# n8n code node: Attach Narratives  (Week 7 — combine-by-position with the Groq response)
import json
THEMES = ["launch", "outage", "funding", "research", "controversy", "hiring"]
TONES  = ["bullish", "bearish", "neutral"]

def merge(_items):
    row = _items[0]["json"]["row"]
    narr = {}
    for it in _items:
        j = it["json"]
        ent = j.get("entity")
        try:
            content = j["choices"][0]["message"]["content"]
            o = json.loads(content)
            theme = o.get("theme") if o.get("theme") in THEMES else "research"
            tone  = o.get("tone")  if o.get("tone")  in TONES  else "neutral"
            narr[ent] = {"narrative": (o.get("narrative") or "").strip(), "theme": theme, "tone": tone}
        except Exception as ex:
            narr[ent] = {"narrative": None, "theme": None, "tone": None, "degraded": True, "reason": str(ex)}
    for e in row.get("leaderboard", []):
        e["narrative"] = narr.get(e.get("entity"))
    row["narratives"] = narr
    return [{"json": row}]


return merge(_items)

# n8n code node: Explode For Story Fetch  (Week 9 — one item per (entity, story))
def build(_items):
    row = _items[0]["json"]
    out = []
    for e in row.get("leaderboard", []):
        tops = e.get("topStories") or ([e["topStory"]] if e.get("topStory") else [])
        for s in tops[:3]:
            if s.get("objectID"):
                out.append({"json": {"entity": e.get("entity"), "ticker": e.get("ticker"),
                                       "row": row, "storyObjectID": s["objectID"]}})
    return out

return build(_items)

# n8n code node: Extract Comment IDs  (Week 9 — one item per (entity, comment id))
def build(_items):
    out = []
    for it in _items:
        j = it["json"]
        for kid in (j.get("kids") or [])[:15]:
            out.append({"json": {"entity": j["entity"], "ticker": j["ticker"],
                                   "row": j["row"], "commentID": kid}})
    return out


return build(_items)

# n8n code node: Clean & Group Comments  (Week 9 — HTML clean, dedupe, group per entity)
import html, re
TAG_RE = re.compile(r"<[^>]+>")
MAX_COMMENT_CHARS = 500
COMMENT_CAP = 15

def clean_comment(raw):
    if not raw:
        return None
    text = TAG_RE.sub(" ", raw)
    text = html.unescape(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text[:MAX_COMMENT_CHARS] if text else None

def build(_items):
    by_entity = {}
    for it in _items:
        j = it["json"]
        if j.get("deleted") or j.get("dead"):
            continue
        c = clean_comment(j.get("text"))
        if not c:
            continue
        ent = j["entity"]
        bucket = by_entity.setdefault(ent, {"ticker": j["ticker"], "row": j["row"], "comments": [], "seen": set()})
        if c not in bucket["seen"]:
            bucket["seen"].add(c)
            bucket["comments"].append(c)
    out = []
    for ent, b in by_entity.items():
        out.append({"json": {"entity": ent, "ticker": b["ticker"], "row": b["row"],
                               "comments": b["comments"][:COMMENT_CAP],
                               "commentsAnalyzed": len(b["comments"][:COMMENT_CAP])}})
    return out


return build(_items)

import json

def build(_items):
    row = _items[0]["json"]["row"]
    try:
        j = _items[0]["json"]
        if "choices" not in j:
            raise RuntimeError(f"Groq error: {j.get('error') or j}")
        content = _items[0]["json"]["choices"][0]["message"]["content"]
        o = json.loads(content)
        row["sectorNarrative"] = {"narrative": (o.get("sectorNarrative") or "").strip(),
                                    "crossEntityThemes": (o.get("crossEntityThemes") or [])[:6],
                                    "degraded": False}
    except Exception as ex:
        row["sectorNarrative"] = {"narrative": None, "crossEntityThemes": [],
                                    "degraded": True, "reason": str(ex)}
    return [{"json": row}]
return build(_items)

